def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if v is None:
        sites = s.get('sites') or []
        n = sum((x.get('occupancy') or 0.0) for x in sites)
        volume = (s.get('lattice') or {}).get('volume_A3')
        v = volume / n if volume is not None and n > 0 else 0.0
    return log1p(max(0.0, v))

def feature(s):
    if not s:
        return 0.0
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    for site in s.get('sites') or []:
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        if r is not None and r > 0:
            total += (site.get('occupancy') or 0.0) * r ** 3
    return 4.0 * pi * total / (3.0 * volume)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [((props.get(x.get('element')) or {}).get('covalent_radius_A') or 0.0) for x in sites]
    nearest = [inf for x in sites]
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        r = radii[i] + radii[j]
        if d is not None and d > 0 and radii[i] > 0 and radii[j] > 0:
            nearest[i] = min(nearest[i], d / r)
    vals = [v for v in nearest if isfinite(v)]
    return sum(vals) / len(vals) if vals else 0.0

