    nearest = [inf for x in sites]
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and radii[i] > 0 and radii[j] > 0:
            nearest[i] = min(nearest[i], d / (radii[i] + radii[j]))
    vals = [v for v in nearest if isfinite(v)]
    if not vals:
        return 0.0
    mean = sum(vals) / len(vals)
    return sqrt(sum((v - mean) ** 2 for v in vals) / len(vals))

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [((props.get(x.get('element')) or {}).get('covalent_radius_A') or 0.0) for x in sites]
    occ = [(x.get('occupancy') or 0.0) for x in sites]
    coord = [0.0 for x in sites]
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and radii[i] > 0 and radii[j] > 0:
            q = d / (1.15 * (radii[i] + radii[j]))
            coord[i] += occ[j] / (1.0 + q ** 12)
    total = sum(occ)
    return sum(o * c for o, c in zip(occ, coord)) / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [((props.get(x.get('element')) or {}).get('covalent_radius_A') or 0.0) for x in sites]
    occ = [(x.get('occupancy') or 0.0) for x in sites]
    coord = [0.0 for x in sites]
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and radii[i] > 0 and radii[j] > 0:
            q = d / (1.15 * (radii[i] + radii[j]))
            coord[i] += occ[j] / (1.0 + q ** 12)
    total = sum(occ)
    if total <= 0:
        return 0.0
    mean = sum(o * c for o, c in zip(occ, coord)) / total
    variance = sum(o * (c - mean) ** 2 for o, c in zip(occ, coord)) / total
    return sqrt(variance) / mean if mean > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [((props.get(x.get('element')) or {}).get('covalent_radius_A') or 0.0) for x in sites]
    occ = [(x.get('occupancy') or 0.0) for x in sites]
    total = sum(occ)
    penalty = 0.0
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and radii[i] > 0 and radii[j] > 0:
            q = d / (radii[i] + radii[j])
            if q < 1.0:
                penalty += occ[i] * occ[j] * (1.0 - q) ** 2
    return penalty / (2.0 * total) if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    elements = [x.get('element') for x in sites]
    radii = [((props.get(e) or {}).get('covalent_radius_A') or 0.0) for e in elements]
    occ = [(x.get('occupancy') or 0.0) for x in sites]
    total, unlike = 0.0, 0.0
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and radii[i] > 0 and radii[j] > 0:
            q = d / (1.15 * (radii[i] + radii[j]))
            w = occ[i] * occ[j] / (1.0 + q ** 12)
            total += w
            if elements[i] != elements[j]:
                unlike += w
    return unlike / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    elements = [x.get('element') for x in sites]
    radii = [((props.get(e) or {}).get('covalent_radius_A') or 0.0) for e in elements]
    occ = [(x.get('occupancy') or 0.0) for x in sites]
    total = sum(occ)
    degree = 0.0
    for b in s.get('neighbors') or []:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if elements[i] == elements[j] and elements[i] in ('H', 'B', 'C', 'N', 'O', 'F', 'Si', 'P', 'S'):
            if d is not None and d > 0 and radii[i] > 0:
                q = d / (2.3 * radii[i])
                degree += occ[i] * occ[j] / (1.0 + q ** 12)
    return degree / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    occ = [(x.get('occupancy') or 0.0) for x in sites]
    nearest = [inf for x in sites]
    bonds = s.get('neighbors') or []
    for b in bonds:
        d = b.get('distance_A')
        if d is not None and d > 0:
            nearest[b['i']] = min(nearest[b['i']], d)
    coord = [0.0 for x in sites]
    for b in bonds:
        d = b.get('distance_A')
        if d is not None and d > 0 and d <= 1.2 * nearest[b['i']]:
            coord[b['i']] += occ[b['j']]
    total = sum(occ)
    return sum(o * c for o, c in zip(occ, coord)) / total if total > 0 else 0.0

