def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    nearest = [inf for x in sites]
    outer = [6.0 for x in sites]
    bonds = s.get('neighbors') or []
    for b in bonds:
        d = b.get('distance_A')
        if d is not None and d > 0:
            nearest[b['i']] = min(nearest[b['i']], d)
    for b in bonds:
        i = b['i']
        d = b.get('distance_A')
        if d is not None and d > 1.2 * nearest[i]:
            outer[i] = min(outer[i], d)
    total, value = 0.0, 0.0
    for i in range(len(sites)):
        if isfinite(nearest[i]) and nearest[i] > 0:
            o = sites[i].get('occupancy') or 0.0
            total += o
            value += o * log(max(1.0, outer[i] / nearest[i]))
    return value / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    sites = s.get('sites') or []
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is not None and volume > 0 and sites:
        electrons = 0.0
        for site in sites:
            v = (props.get(site.get('element')) or {}).get('valence_electrons')
            if v is not None:
                electrons += (site.get('occupancy') or 0.0) * v
        return electrons / volume
    vpa = s.get('volume_per_atom_A3')
    if vpa is None or vpa <= 0:
        return 0.0
    electrons, total = 0.0, 0.0
    for element, fraction in (s.get('composition') or {}).items():
        v = (props.get(element) or {}).get('valence_electrons')
        if fraction is not None and fraction > 0 and v is not None:
            electrons += fraction * v
            total += fraction
    return electrons / (total * vpa) if total > 0 else 0.0
